"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["67805"],{81210(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.regra_de_aplicabilidade_divergente","status":422,"titulo":"A mesma modalidade foi copiada com regras de aplicabilidade diferentes em ofertas do processo"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.regra_de_aplicabilidade_divergente","requisitos":[],"oQueAconteceu":["Cada modalidade tem uma regra, pr\xf3pria do processo, que decide quem concorre a\\nela. Na distribui\xe7\xe3o de vagas, todas as ofertas de curso copiam as modalidades\\ndo cadastro na mesma grava\xe7\xe3o; por isso a mesma modalidade deve chegar com a\\nmesma regra em todas as ofertas. A distribui\xe7\xe3o enviada traz a mesma modalidade\\ncom regras diferentes em ofertas distintas.","Em condi\xe7\xf5es normais isso s\xf3 acontece quando o cadastro da modalidade foi\\nalterado no meio da grava\xe7\xe3o. Na defini\xe7\xe3o da distribui\xe7\xe3o, a recusa n\xe3o grava\\nnada e a distribui\xe7\xe3o anterior continua como estava. A mensagem da resposta\\nindica a modalidade."],"comoResolver":["Repita a defini\xe7\xe3o da distribui\xe7\xe3o de vagas: a nova grava\xe7\xe3o copia de novo as\\nmodalidades do cadastro, j\xe1 no estado em que ele est\xe1."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);